//! The bundled IntelliJ themes and editor schemes (generated by `tools/themes`).

use archipel_kit::egui::Color32;
use archipel_kit::theme::{EditorScheme, EffectKind};
use archipel_kit::{Theme, install};
use std::collections::BTreeSet;

fn luminance(color: Color32) -> f32 {
    let channel = |value: u8| {
        let value = f32::from(value) / 255.0;
        if value <= 0.03928 {
            value / 12.92
        } else {
            ((value + 0.055) / 1.055).powf(2.4)
        }
    };
    0.2126 * channel(color.r()) + 0.7152 * channel(color.g()) + 0.0722 * channel(color.b())
}

fn contrast(a: Color32, b: Color32) -> f32 {
    let (a, b) = (luminance(a), luminance(b));
    (a.max(b) + 0.05) / (a.min(b) + 0.05)
}

#[test]
fn every_bundled_theme_builds_with_a_unique_id() {
    let all = Theme::all();
    assert_eq!(all.len(), 14, "2 Archipel themes + 12 IntelliJ themes");
    let ids: BTreeSet<_> = all.iter().map(|info| info.id).collect();
    assert_eq!(ids.len(), all.len(), "ids are unique");
    for info in all {
        let theme = (info.constructor)();
        assert_eq!(theme.dark, info.dark, "{}: brightness", info.id);
        assert_eq!(Theme::by_id(info.id).as_ref(), Some(&theme), "{}", info.id);
    }
    assert!(Theme::by_id("nope").is_none());
}

#[test]
fn the_measured_themes_are_unchanged_and_still_the_defaults() {
    assert_eq!(Theme::dark().name, "Archipel Dark");
    assert_eq!(Theme::light().name, "Archipel Light");
    assert_eq!(
        Theme::dark().colors.frame,
        Color32::from_rgb(0x26, 0x28, 0x2C)
    );
    assert_eq!(
        Theme::light().colors.accent,
        Color32::from_rgb(0x38, 0x71, 0xE1)
    );
    assert_eq!(Theme::default(), Theme::dark());
}

#[test]
fn islands_themes_match_the_measured_palettes_where_the_data_has_a_key() {
    for (generated, measured) in [
        (Theme::islands_dark(), Theme::dark()),
        (Theme::islands_light(), Theme::light()),
    ] {
        let (g, m) = (generated.colors, measured.colors);
        assert_eq!(g.frame, m.frame);
        assert_eq!(g.island, m.island);
        assert_eq!(g.text, m.text);
        assert_eq!(g.accent, m.accent);
        assert_eq!(g.selection, m.selection);
        assert_eq!(g.border, m.border);
        assert_eq!(g.hover, m.hover);
        assert_eq!(g.banner_error, m.banner_error);
        let (g, m) = (generated.editor, measured.editor);
        assert_eq!(g.background, m.background);
        assert_eq!(g.text, m.text);
        assert_eq!(g.keyword, m.keyword);
        assert_eq!(g.string, m.string);
        assert_eq!(g.caret_row, m.caret_row);
    }
}

#[test]
fn ui_keys_resolve_through_parents_names_and_star_entries() {
    let theme = Theme::islands_dark();
    assert_eq!(
        theme.ui_theme_chain(),
        ["Darcula", "ExperimentalDark", "Islands Dark"]
    );
    // An explicit key, a palette name and a `*` key.
    assert_eq!(
        theme.ui_color("ToolWindow.background"),
        Some(Color32::from_rgb(0x19, 0x1A, 0x1C))
    );
    assert_eq!(
        theme.ui_color("Tree.selectionBackground"),
        Some(Color32::from_rgb(0x2A, 0x43, 0x71))
    );
    assert_eq!(theme.ui_color("No.such.key"), None);
    assert_eq!(theme.ui_number("Island.arc"), Some(20.0));
    assert_eq!(theme.ui_number("Island.borderWidth"), Some(6.0));
    assert_eq!(theme.ui_size("Button.minimumSize"), Some([72.0, 28.0]));
    assert_eq!(
        theme.ui_insets("TabbedPane.tabInsets"),
        Some([0.0, 12.0, 0.0, 12.0])
    );
    // A theme built by hand has no tables.
    let mut by_hand = Theme::dark();
    by_hand.source = Default::default();
    assert_eq!(by_hand.ui_color("ToolWindow.background"), None);
    assert!(by_hand.ui_theme_chain().is_empty());
}

#[test]
fn classic_and_new_ui_themes_keep_their_own_values() {
    let darcula = Theme::darcula();
    assert_eq!(darcula.ui_theme_chain(), ["Darcula"]);
    assert_eq!(darcula.colors.island, Color32::from_rgb(0x3C, 0x3F, 0x41));
    assert_eq!(
        darcula.editor.background,
        Color32::from_rgb(0x2B, 0x2B, 0x2B)
    );
    let new_ui = Theme::new_ui_dark();
    assert_eq!(new_ui.colors.island, Color32::from_rgb(0x2B, 0x2D, 0x30));
    let light = Theme::intellij_light();
    assert_eq!(light.name, "IntelliJ Light");
    assert!(!light.dark);
    assert_eq!(
        light.editor_scheme().map(|s| s.id()),
        Some("intellij_light")
    );
}

#[test]
fn text_is_readable_in_every_theme() {
    for info in Theme::all() {
        let theme = (info.constructor)();
        let c = theme.colors;
        for (name, fg, bg, min) in [
            ("text on island", c.text, c.island, 4.5),
            ("text on frame", c.text, c.frame, 4.5),
            ("text on popup", c.text, c.popup, 4.5),
            ("text on field", c.text, c.field, 4.5),
            ("secondary on island", c.text_secondary, c.island, 3.0),
            ("strong text on island", c.text_strong, c.island, 4.5),
            ("text on selection", c.text, c.selection, 2.5),
            ("link on island", c.link, c.island, 3.0),
            ("error on island", c.error, c.island, 3.0),
            (
                "editor text",
                theme.editor.text,
                theme.editor.background,
                4.5,
            ),
            (
                "editor keyword",
                theme.editor.keyword,
                theme.editor.background,
                2.5,
            ),
            (
                "editor string",
                theme.editor.string,
                theme.editor.background,
                2.5,
            ),
        ] {
            let ratio = contrast(fg, bg);
            assert!(
                ratio >= min,
                "{}: {name} has contrast {ratio:.2}, expected at least {min}",
                info.id
            );
        }
        for (name, color) in [
            ("island", c.island),
            ("frame", c.frame),
            ("popup", c.popup),
            ("field", c.field),
            ("text", c.text),
            ("accent", c.accent),
            ("editor background", theme.editor.background),
            ("editor text", theme.editor.text),
        ] {
            assert_eq!(color.a(), 255, "{}: {name} is opaque", info.id);
        }
    }
}

#[test]
fn schemes_cover_the_bundled_set_and_inherit() {
    let schemes = EditorScheme::all();
    assert_eq!(schemes.len(), 18);
    let ids: BTreeSet<_> = schemes.iter().map(|s| s.id()).collect();
    assert_eq!(ids.len(), 18);
    for expected in [
        "default",
        "darcula",
        "islands_dark",
        "new_ui_dark",
        "new_ui_light",
        "intellij_light",
        "high_contrast",
        "monokai",
        "twilight",
        "blackboard",
        "cobalt",
        "all_hallows_eve",
        "warm_neon",
        "github",
        "vibrant_ink",
        "rails_casts",
    ] {
        assert!(EditorScheme::by_id(expected).is_some(), "{expected}");
    }
    let monokai = EditorScheme::by_id("monokai").expect("monokai");
    assert!(monokai.dark());
    assert_eq!(monokai.parent().map(|p| p.id()), Some("darcula"));
    assert_eq!(
        monokai.parent().and_then(|p| p.parent()).map(|p| p.id()),
        Some("default")
    );
    // Own value, inherited value, and an inherited attribute list.
    assert_eq!(
        monokai.color("CARET_COLOR"),
        Some(Color32::from_rgb(0xF8, 0xF8, 0xF0))
    );
    assert!(monokai.color("RIGHT_MARGIN_COLOR").is_some());
    assert!(monokai.attribute_names().contains(&"DEFAULT_KEYWORD"));
    let keyword = monokai.attributes("DEFAULT_KEYWORD").expect("keyword");
    assert_eq!(
        keyword.foreground,
        Some(Color32::from_rgb(0xF9, 0x26, 0x72))
    );
    assert!(monokai.attributes("NO_SUCH_KEY").is_none());
}

#[test]
fn attributes_resolve_base_attributes_effects_and_font_styles() {
    let islands = EditorScheme::by_id("islands_dark").expect("scheme");
    // `ANNOTATION_NAME_ATTRIBUTES` is `baseAttributes="DEFAULT_METADATA"`.
    let annotation = islands
        .attributes("ANNOTATION_NAME_ATTRIBUTES")
        .expect("annotation");
    let metadata = islands.attributes("DEFAULT_METADATA").expect("metadata");
    assert_eq!(annotation.foreground, metadata.foreground);
    assert!(annotation.foreground.is_some());
    // Effects and stripes.
    let errors = islands.attributes("ERRORS_ATTRIBUTES").expect("errors");
    assert_eq!(
        errors.effect.map(|e| e.kind),
        Some(EffectKind::WaveUnderscore)
    );
    assert_eq!(errors.stripe, Some(Color32::from_rgb(0xD6, 0x4D, 0x5B)));
    let deprecated = EditorScheme::by_id("darcula")
        .and_then(|s| s.attributes("DEPRECATED_ATTRIBUTES"))
        .expect("deprecated");
    assert_eq!(
        deprecated.effect.map(|e| e.kind),
        Some(EffectKind::Strikeout)
    );
    let constant = islands.attributes("DEFAULT_CONSTANT").expect("constant");
    assert!(constant.italic && !constant.bold);
}

#[test]
fn any_ui_theme_combines_with_any_scheme() {
    let base = Theme::islands_light();
    let before = base.colors;
    let combined = base.with_editor_scheme(EditorScheme::by_id("monokai").expect("monokai"));
    assert_eq!(combined.colors, before, "workbench colors stay");
    assert_eq!(
        combined.editor.background,
        Color32::from_rgb(0x27, 0x28, 0x22)
    );
    assert_eq!(combined.editor_scheme().map(|s| s.id()), Some("monokai"));
    assert_eq!(
        combined
            .text_attributes("DEFAULT_KEYWORD")
            .and_then(|a| a.foreground),
        Some(Color32::from_rgb(0xF9, 0x26, 0x72))
    );
    for scheme in EditorScheme::all() {
        let theme = Theme::darcula().with_editor_scheme(*scheme);
        assert_eq!(theme.editor, scheme.editor_colors(), "{}", scheme.id());
    }
}

#[test]
fn every_scheme_is_readable_and_complete() {
    for scheme in EditorScheme::all() {
        let e = scheme.editor_colors();
        let id = scheme.id();
        assert_eq!(e.background.a(), 255, "{id}: opaque background");
        assert_eq!(
            luminance(e.background) < 0.18,
            scheme.dark(),
            "{id}: brightness"
        );
        for (name, color, min) in [
            ("text", e.text, 4.5),
            ("string", e.string, 2.5),
            ("number", e.number, 2.5),
            ("keyword", e.keyword, 2.5),
            ("comment", e.comment, 1.8),
            ("line numbers", e.line_number, 1.8),
        ] {
            let ratio = contrast(color, e.background);
            assert!(
                ratio >= min,
                "{id}: {name} has contrast {ratio:.2}, expected {min}"
            );
        }
        // The attribute table feeds a syntax highlighter: the basics resolve everywhere.
        for key in [
            "TEXT",
            "DEFAULT_KEYWORD",
            "DEFAULT_STRING",
            "DEFAULT_LINE_COMMENT",
        ] {
            assert!(scheme.attributes(key).is_some(), "{id}: {key}");
        }
    }
}

#[test]
fn every_theme_applies_to_a_context() {
    let ctx = archipel_kit::egui::Context::default();
    install(&ctx, Theme::dark());
    for info in Theme::all() {
        let theme = (info.constructor)();
        let colors = theme.colors;
        theme.apply(&ctx);
        assert_eq!(Theme::colors(&ctx), colors, "{}", info.id);
        assert_eq!(ctx.style().visuals.dark_mode, info.dark, "{}", info.id);
    }
}
